import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import { discoverModules } from "./loader.ts";

const HEADER = `/* eslint-disable */
/**
 * Generated by incibase. Do not edit; it is rewritten on every change.
 */
`;

const NOT_IN_API = new Set(["crons", "http"]);

/** Writes `file` only when its content changed. Returns whether it wrote. */
export function writeIfChanged(file: string, content: string): boolean {
  if (existsSync(file) && readFileSync(file, "utf8") === content) return false;
  writeFileSync(file, content);
  return true;
}

function identifier(modulePath: string) {
  return modulePath.replace(/\//g, "_");
}

/**
 * Generates `<dir>/_generated/{api,server,dataModel}.ts`. Types only depend on
 * file names and TypeScript inference, so this never runs user code.
 */
export function codegen(dir: string): { changed: string[] } {
  const { modules, schemaFile } = discoverModules(dir);
  const out = join(dir, "_generated");
  mkdirSync(out, { recursive: true });
  const apiModules = modules.filter((m) => !NOT_IN_API.has(m.modulePath));

  const api =
    HEADER +
    `import { anyApi, type ApiFromModules, type FilterApi } from "incibase";\n` +
    apiModules.map((m) => `import type * as ${identifier(m.modulePath)} from "../${m.modulePath}";\n`).join("") +
    `\ndeclare const fullApi: ApiFromModules<{\n` +
    apiModules.map((m) => `  ${JSON.stringify(m.modulePath)}: typeof ${identifier(m.modulePath)};\n`).join("") +
    `}>;\n\n` +
    `/** References to public functions, e.g. \`api.messages.list\`. */\n` +
    `export const api: FilterApi<typeof fullApi, "public"> = anyApi;\n` +
    `/** References to internal functions, for ctx.runQuery, ctx.scheduler and crons. */\n` +
    `export const internal: FilterApi<typeof fullApi, "internal"> = anyApi;\n`;

  const schemaImport = schemaFile ? `../${basename(schemaFile).replace(/\.[^.]+$/, "")}` : null;
  const server =
    HEADER +
    `import {\n` +
    `  makeFunctionBuilders,\n` +
    `  type ActionCtx as GenericActionCtx,\n` +
    (schemaImport ? `  type DataModelFromSchema,\n` : `  type GenericDataModel,\n`) +
    `  type MutationCtx as GenericMutationCtx,\n` +
    `  type QueryCtx as GenericQueryCtx,\n` +
    `} from "incibase/server";\n` +
    (schemaImport
      ? `import type schema from ${JSON.stringify(schemaImport)};\n\nexport type DataModel = DataModelFromSchema<typeof schema>;\n`
      : `\nexport type DataModel = GenericDataModel;\n`) +
    `export type QueryCtx = GenericQueryCtx<DataModel>;\n` +
    `export type MutationCtx = GenericMutationCtx<DataModel>;\n` +
    `export type ActionCtx = GenericActionCtx;\n\n` +
    `export const { query, internalQuery, mutation, internalMutation, action, internalAction, httpAction } =\n` +
    `  makeFunctionBuilders<DataModel>();\n`;

  const dataModel =
    HEADER +
    `import type { Id as GenericId } from "incibase";\n` +
    `import type { DataModel } from "./server";\n\n` +
    `export type { DataModel };\n` +
    `export type TableNames = keyof DataModel & string;\n` +
    `export type Doc<T extends TableNames> = DataModel[T]["document"];\n` +
    `export type Id<T extends TableNames> = GenericId<T>;\n`;

  const changed: string[] = [];
  for (const [name, content] of [
    ["api.ts", api],
    ["server.ts", server],
    ["dataModel.ts", dataModel],
  ] as const) {
    if (writeIfChanged(join(out, name), content)) changed.push(name);
  }
  return { changed };
}
